#!/usr/bin/env node
/**
 * Copy the freshly built UMD bundle into the R package.
 *
 * msaviewr is an htmlwidget, so R has to find the JavaScript inside the
 * installed package -- installing an R package runs no node, and pointing the
 * htmlDependency at a CDN would break offline use and self-contained R Markdown
 * output. The bundle is therefore vendored, which means it goes stale the moment
 * anything in packages/lib changes unless something refreshes it.
 *
 * scripts/release.js calls this after `pnpm build`, so every published release
 * ships the JavaScript that release was cut from. Run it by hand with
 * `pnpm sync:r-bundle` (after a build) to refresh in between.
 *
 * The bundle is stamped with a version banner so CI can check the committed
 * artifact itself rather than a sidecar file -- see the `r-package` job.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')

const src = path.join(rootDir, 'packages/lib/bundle/index.js')
const rPkg = path.join(rootDir, 'packages/r-msaview')
const dest = path.join(rPkg, 'inst/htmlwidgets/lib/react-msaview.umd.js')
const coreDest = path.join(rPkg, 'inst/js/msaview-core.js')
const yamlPath = path.join(rPkg, 'inst/htmlwidgets/msaview.yaml')
const descriptionPath = path.join(rPkg, 'DESCRIPTION')

export const BANNER_PREFIX = '/* react-msaview '

export function bannerFor(version) {
  return `${BANNER_PREFIX}${version} - generated by scripts/sync-r-bundle.mjs, do not edit */\n`
}

export function readLibVersion() {
  return JSON.parse(
    fs.readFileSync(path.join(rootDir, 'packages/lib/package.json'), 'utf8'),
  ).version
}

/** the version stamped into the vendored bundle, or undefined if unstamped */
export function readBundleVersion(file = dest) {
  const fd = fs.openSync(file, 'r')
  try {
    const buf = Buffer.alloc(200)
    const n = fs.readSync(fd, buf, 0, buf.length, 0)
    return /^\/\* react-msaview (\S+) /.exec(buf.subarray(0, n).toString())?.[1]
  } finally {
    fs.closeSync(fd)
  }
}

export function readYamlVersion() {
  return /^\s*version:\s*(\S+)/m.exec(fs.readFileSync(yamlPath, 'utf8'))?.[1]
}

export function readDescriptionVersion() {
  return /^Version:\s*(\S+)/m.exec(
    fs.readFileSync(descriptionPath, 'utf8'),
  )?.[1]
}

function sync() {
  if (!fs.existsSync(src)) {
    console.error(
      `${src} not found - run \`pnpm build\` (or \`pnpm --filter react-msaview build:umd\`) first`,
    )
    process.exit(1)
  }
  const version = readLibVersion()

  fs.mkdirSync(path.dirname(dest), { recursive: true })
  fs.writeFileSync(dest, bannerFor(version) + fs.readFileSync(src, 'utf8'))

  // htmlwidgets keys its dependency cache on this version, so it has to move
  // with the bundle or a page can serve a stale copy alongside a new widget
  fs.writeFileSync(
    yamlPath,
    fs
      .readFileSync(yamlPath, 'utf8')
      .replace(/^(\s*version:\s*)\S+/m, `$1${version}`),
  )

  // msaviewr is the same release as everything else in the workspace: it ships
  // this bundle and nothing but this bundle
  fs.writeFileSync(
    descriptionPath,
    fs
      .readFileSync(descriptionPath, 'utf8')
      .replace(/^(Version:\s*)\S+/m, `$1${version}`),
  )

  const kb = Math.round(fs.statSync(dest).size / 1024)
  console.log(`Synced react-msaview.umd.js to ${version} (${kb} KB)`)
}

/**
 * Fail if the vendored bundle is not the one this version of the lib builds.
 * Checks the stamp in the artifact itself, not a sidecar, so hand-editing the
 * yaml cannot make a stale bundle look current.
 */
function check() {
  const version = readLibVersion()
  const problems = [
    ['bundle banner', readBundleVersion()],
    ['msaview-core.js banner', readBundleVersion(coreDest)],
    ['msaview.yaml version', readYamlVersion()],
    ['DESCRIPTION version', readDescriptionVersion()],
  ].filter(([, found]) => found !== version)

  if (problems.length > 0) {
    for (const [what, found] of problems) {
      console.error(`${what} is ${found ?? '(missing)'}, expected ${version}`)
    }
    console.error(
      '\nThe R package vendors the UMD bundle and the QuickJS core. Run `pnpm build && pnpm sync:r-bundle`',
    )
    process.exit(1)
  }
  console.log(`R bundle is in sync at ${version}`)
}

if (import.meta.url === `file://${process.argv[1]}`) {
  if (process.argv.includes('--check')) {
    check()
  } else {
    sync()
  }
}
